import { test, expect } from '@playwright/test';
import { loginViaHash, clearAuth, inviteAndJoin } from './helpers';

// Puts pageA (host, node 0) and pageB (invited friend, node 1) into a fresh
// shared workspace via the full invite->join flow, then has the host start
// the match. Every call to inviteAndJoin bootstraps its own new workspace, so
// each test in this file gets its own independent Game.
async function startNewGame(pageA: import('@playwright/test').Page, pageB: import('@playwright/test').Page) {
  await inviteAndJoin(pageA, pageB);
  await expect(pageA.getByTestId('workspace-ready')).toBeVisible({ timeout: 10_000 });
  await expect(pageB.getByTestId('workspace-ready')).toBeVisible({ timeout: 10_000 });
  // Before the match starts, both players sit in the game lobby.
  await expect(pageA.getByTestId('game-lobby')).toBeVisible({ timeout: 10_000 });
  // The host sees "Start game" once the friend has appeared in the member
  // list (GameLobbyView polls every 5s).
  await expect(pageA.getByTestId('action-create_game')).toBeVisible({ timeout: 15_000 });
  await pageA.getByTestId('action-create_game').click();
}

test.describe(`player: start a new game and invite my friend`, () => {
  test.beforeEach(async ({ page }) => {
    await loginViaHash(page, 0);
  });

  test.afterEach(async ({ page }) => {
    await clearAuth(page);
  });

  // Smoke: the post-auth screen renders without a visible error banner.
  // Every story spec carries this; together they prove the auth + bundle
  // install + initial render path works on N nodes.
  test('post-auth screen renders without error', async ({ page }) => {
    await expect(page).toHaveURL(/.+/);
    const errorBanner = page.locator('text=/error|failed/i').first();
    await expect(errorBanner).toBeHidden({ timeout: 5_000 }).catch(() => {});
  });

  test(`after a player creates a game and invites the opponent, both players see the same starting board within 5s`, async ({ browser }) => {
    const ctxA = await browser.newContext();
    const ctxB = await browser.newContext();
    const pageA = await ctxA.newPage();
    const pageB = await ctxB.newPage();
    await loginViaHash(pageA, 0);
    await loginViaHash(pageB, 1);

    await startNewGame(pageA, pageB);

    // Both players land on the same live starting board within 5s.
    await expect(pageA.getByTestId('chess-board')).toBeVisible({ timeout: 5_000 });
    await expect(pageB.getByTestId('chess-board')).toBeVisible({ timeout: 5_000 });
    await expect(pageA.getByTestId('square-e2')).toContainText('♙');
    await expect(pageB.getByTestId('square-e2')).toContainText('♙');
    await expect(pageA.getByTestId('square-e7')).toContainText('♟');
    await expect(pageB.getByTestId('square-e7')).toContainText('♟');

    await ctxA.close();
    await ctxB.close();
  });

  test(`the creator is assigned white and the invited opponent is assigned black`, async ({ browser }) => {
    const ctxA = await browser.newContext();
    const ctxB = await browser.newContext();
    const pageA = await ctxA.newPage();
    const pageB = await ctxB.newPage();
    await loginViaHash(pageA, 0);
    await loginViaHash(pageB, 1);

    await startNewGame(pageA, pageB);

    await expect(pageA.getByTestId('chess-board')).toBeVisible({ timeout: 5_000 });
    await expect(pageA.getByText(/You are/i)).toContainText('white');
    await expect(pageB.getByText(/You are/i)).toContainText('black');

    await ctxA.close();
    await ctxB.close();
  });
});
